int sctp_get_assoc_stats(struct sock *sk, int len, char __user *optval, int __user *optlen)
{
    struct sctp_association *asoc;
    struct sctp_assoc_stats stats;
    int ret = 0;

    if (len < sizeof(struct sctp_assoc_stats))
        return -EINVAL;

    asoc = sctp_id2assoc(sk, 0);
    if (!asoc)
        return -EINVAL;

    memset(&stats, 0, sizeof(stats));

    stats.assoc_id = asoc->assoc_id;
    stats.cnt = asoc->stats->cnt;
    stats.cnt_rtx = asoc->stats->cnt_rtx;
    stats.cnt_tsn = asoc->stats->cnt_tsn;
    stats.cnt_gap = asoc->stats->cnt_gap;
    stats.cnt_dup = asoc->stats->cnt_dup;
    stats.rto_max = asoc->rto_max;

    if (copy_to_user(optval, &stats, sizeof(stats)))
        return -EFAULT;

    if (optlen && put_user(sizeof(stats), optlen))
        return -EFAULT;

    return 0;
}

int sctp_get_assoc_stats(struct sock *sk, int len, char __user *optval, int __user *optlen)
