        return -EFAULT;

    if (put_user(sizeof(stats), optlen))
        return -EFAULT;

    return ret;
}

int sctp_get_association_stats(struct sock *sk, int len, char __user *optval, int __user *optlen) {
    struct sctp_association *asoc;
    struct sctp_stats stats;
    int ret = 0;

    if (len < sizeof(struct sctp_stats))
        return -EINVAL;

    asoc = sctp_get_association(sk);
    if (!asoc)
        return -ENOENT;

    memset(&stats, 0, sizeof(stats));
    stats.assoc_id = asoc->assoc_id;
    stats.cwnd = asoc->cwnd;
    stats.ssthresh = asoc->ssthresh;
    stats.partial_delivery_point = asoc->partial_delivery_point;
    stats.rto = asoc->rto;
    stats.max_rto = max(stats.max_rto, asoc->rto);
    stats.min_rto = min(stats.min_rto, asoc->rto);
    stats.pmtu = asoc->pmtu;
    stats.state = asoc->state;

    if (copy_to_user(optval, &stats, sizeof(stats)))
        return -EFAULT;

    if (put_user(sizeof(stats), optlen))
        return -EFAULT;

    return 0;
}

int sctp_get_assoc_stats(struct sock *sk, int len, char __user *optval, int __user *optlen) {
    struct sctp_association *asoc;
    struct sctp_assoc_stats stats;
    int ret = 0;

    if (len < sizeof(stats)) {
        return -EINVAL;
    }

    asoc = sctp_id2assoc(sk, sctp_get_id(sk));
    if (!asoc) {
        return -ENOENT;
    }

    memset(&stats, 0, sizeof(stats));

    stats.cnt_rcv_total = asoc->stats.cnt_rcv_total;
    stats.cnt_snd_total = asoc->stats.cnt_snd_total;
    stats.cnt_retrans = asoc->stats.cnt_retrans;
    stats.cnt_fast_retrans = asoc->stats.cnt_fast_retrans;
    stats.cnt_rto = asoc->stats.cnt_rto;
    stats.cnt_rtx_timeout = asoc->stats.cnt_rtx_timeout;
    stats.cnt_t3_rtx = asoc->stats.cnt_t3_rtx;
    stats.rto_max = asoc->rto_max;

    if (copy_to_user(optval, &stats, sizeof(stats)) != 0) {
        return -EFAULT;
    }

    if (put_user(sizeof(stats), optlen) != 0) {
        return -EFAULT;
    }

    return ret;
}

int sctp_get_assoc_stats(struct sock *sk, int len, char __user *optval, int __user *optlen)
{
    struct sctp_association *asoc;
    struct sctp_stats sctp_stats;
    int ret = 0;

    if (len < sizeof(sctp_stats)) {
        return -EINVAL;
    }

    asoc = sctp_id2assoc(sk, 0);
    if (!asoc) {
        return -ENOENT;
    }

    sctp_stats.assoc_id = asoc->assoc_id;
    sctp_stats.cumu_flight = asoc->stats.cumu_flight;
    sctp_stats.rtx_cnt = asoc->stats.rtx_cnt;
    sctp_stats.total_retrans = asoc->stats.total_retrans;
    sctp_stats.total_tsn_sent = asoc->stats.total_tsn_sent;
    sctp_stats.total_tsn_recd = asoc->stats.total_tsn_recd;
    sctp_stats.pmtu = asoc->pmtu;
    sctp_stats.max_rto = asoc->rto_max;
    sctp_stats.min_rto = asoc->rto_min;
    sctp_stats.cur_rto = asoc->rto;

    if (copy_to_user(optval, &sctp_stats, sizeof(sctp_stats))) {
        return -EFAULT;
    }

    if (put_user(sizeof(sctp_stats), optlen)) {
        return -EFAULT;
    }

    return ret;
}
